/** Persistent ownership and progression; bounded original Zoan moves and single-use power imprints. */
public final class ZoanPowers {
    public static final List<String> FRUITS=List.of("fox","axolotl");
    private static final Identifier SPEED=Identifier.fromNamespaceAndPath("creeperborn","zoan_speed"),STABILITY=Identifier.fromNamespaceAndPath("creeperborn","zoan_stability");
    private static final class State {
        Player p;ServerLevel level;String fruit;int mode,held=-1,keys,dashes=9,dashTicks;long press,heartbeat,guardUntil,regenUntil,lastDash=-10000,recent=-10000,inputUntil;Vec3 dashDirection;boolean flight;int synced=-1;
    }
    private static final class Shot {Player p;ServerLevel level;String fruit,power;Vec3 at,dir;double distance,range,speed,radius;float damage;int kind;Display.BlockDisplay visual;}
    private record Visual(Player p,Display.BlockDisplay entity,long until){}
    private static final Map<UUID,State> states=new HashMap<>();
    private static final List<Shot> shots=new ArrayList<>();
    private static final Map<UUID,Visual> visuals=new HashMap<>();
    private record Origin(Player p,String power){}
    private static final ThreadLocal<Origin> origin=new ThreadLocal<>();
    private static final Map<UUID,Integer> clientStates=new HashMap<>();
    private static int clientFlags(Player p){return clientStates.getOrDefault(p.getUUID(),0);}
    private static long now(Entity e){return e.level().getGameTime();}
    public static boolean unlocked(Player p,String f){return FRUITS.contains(f)&&p.entityTags().contains("cb_fruit_"+f)&&p.getUUID().equals(FruitClaims.owner(f));}
    public static boolean owns(Player p){return unlocked(p,"fox")||unlocked(p,"axolotl");}
    public static String owned(Player p){return unlocked(p,"fox")?"fox":unlocked(p,"axolotl")?"axolotl":"";}
    public static String current(Player p){String f=owned(p);return !f.isEmpty()&&p.entityTags().contains("cb_mode_fruit")&&Dark.matches(p,f)?f:"";}
    public static int tier(Player p,String f){return unlocked(p,f)?Rubber.progressTier(Mastery.get(p,"cb_"+f+"_uses_"),Mastery.get(p,"cb_"+f+"_time_")):0;}
    public static void grant(Player p,String f,int t){Mastery.set(p,"cb_"+f+"_uses_",t>=3?40:t==2?10:0);Mastery.set(p,"cb_"+f+"_time_",t>=3?3600:t==2?300:0);State s=states.get(p.getUUID());if(s!=null){int next=f.equals("fox")?(t>=2?2:1):(t>=3?3:1);change(s,next);}}
    private static State state(Player p,String f){State s=states.computeIfAbsent(p.getUUID(),id->new State());s.p=p;s.level=(ServerLevel)p.level();s.fruit=f;return s;}
    public static boolean consume(Player p,ItemStack item,String f){if(!FRUITS.contains(f)||item.isEmpty()||!Relics.kind(item).equals("fruit:"+f)||!FruitClaims.claimItem(p,item,f))return false;p.addTag("cb_fruit_"+f);grant(p,f,Relics.captureTier(item));if(Dark.unlocked(p))Dark.selectConsumed(p,f);p.addTag("cb_mode_fruit");State s=state(p,f);change(s,f.equals("fox")&&tier(p,f)>=2?2:1);item.shrink(1);return true;}
    private static boolean valid(State s){return s.p.isAlive()&&!s.p.isRemoved()&&s.p.level()==s.level&&!s.p.isSpectator()&&unlocked(s.p,s.fruit)&&Dark.matches(s.p,s.fruit)&&!Dark.suppressed(s.p)&&!WaterRules.suppressed(s.p)&&!StringFruit.controlled(s.p);}
    private static boolean restrained(Player p){return Shackles.rooted(p)||CelestialPowers.rooted(p)||NaturePowers.rooted(p)||ClimatePowers.rooted(p)||PairPowers.rooted(p)||Dark.rooted(p)||StringFruit.controlled(p);}
    private static long value(Player p,String key){for(String tag:p.entityTags())if(tag.startsWith(key))try{return Long.parseLong(tag.substring(key.length()));}catch(NumberFormatException ignored){}return 0;}
    private static void value(Player p,String key,long n){for(String tag:Set.copyOf(p.entityTags()))if(tag.startsWith(key))p.removeTag(tag);p.addTag(key+n);}
    private static void credit(State s){if(now(s.p)-s.recent>=20)Mastery.set(s.p,"cb_"+s.fruit+"_uses_",Mastery.get(s.p,"cb_"+s.fruit+"_uses_")+1);s.recent=now(s.p);}
    public static int mode(Player p){if(!(p.level() instanceof ServerLevel))return (clientFlags(p)>>2)&3;State s=states.get(p.getUUID());return s!=null&&s.p==p&&p.level()==s.level?s.mode:0;}
    public static void clientState(UUID id,int flags){if(flags==0)clientStates.remove(id);else clientStates.put(id,flags);}
    public static void clearClient(){clientStates.clear();}
    public static boolean small(Player p){return (p.level() instanceof ServerLevel?unlocked(p,"axolotl"):(clientFlags(p)&3)==2)&&mode(p)==1;}
    public static boolean giantFox(Player p){return (p.level() instanceof ServerLevel?unlocked(p,"fox"):(clientFlags(p)&3)==1)&&mode(p)==3;}
    public static boolean giantAx(Player p){return (p.level() instanceof ServerLevel?unlocked(p,"axolotl"):(clientFlags(p)&3)==2)&&mode(p)==3;}
    public static boolean aquatic(Player p){return unlocked(p,"axolotl");}
    public static EntityDimensions dimensions(Player p){int m=mode(p);if(m==0)return null;if(giantFox(p))return EntityDimensions.scalable(6.8f,5).withEyeHeight(4.1f);if(giantAx(p))return EntityDimensions.scalable(7.6f,2.8f).withEyeHeight(2.1f);if(small(p))return EntityDimensions.scalable(.65f,.45f).withEyeHeight(.32f);return null;}
    public static double headHeight(Player p){var d=dimensions(p);return d==null?0:d.eyeHeight();}
    public static boolean swim(Player p,Vec3 input){if(!small(p)||!p.isInWater()||p.isPassenger()||restrained(p))return false;p.moveRelative(.12f,input);Vec3 v=p.getDeltaMovement();if(v.lengthSqr()>2.25)v=v.normalize().scale(1.5);p.move(MoverType.SELF,v);p.setDeltaMovement(v.scale(.85));return true;}
    public static void recover(Player p){for(String tag:Set.copyOf(p.entityTags()))if(tag.startsWith("cb_zoan_flight_")){String[] v=tag.substring(15).split("_");try{if(Boolean.parseBoolean(v[0])&&!p.isCreative()&&!p.isSpectator()){p.getAbilities().mayfly=false;p.getAbilities().flying=false;}else if(!p.isSpectator())p.getAbilities().flying=Boolean.parseBoolean(v[2]);p.getAbilities().setFlyingSpeed(Float.parseFloat(v[1]));p.onUpdateAbilities();}catch(RuntimeException ignored){}p.removeTag(tag);}attributes(p,0,"");}
    private static void flight(State s,boolean on){Player p=s.p;if(on==s.flight)return;if(on){p.addTag("cb_zoan_flight_"+(!p.getAbilities().mayfly)+"_"+p.getAbilities().getFlyingSpeed()+"_"+p.getAbilities().flying);s.flight=true;p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.getAbilities().setFlyingSpeed(.11f);p.onUpdateAbilities();}else{s.flight=false;recover(p);}p.resetFallDistance();}
    private static void attributes(Player p,int mode,String f){var speed=p.getAttribute(Attributes.MOVEMENT_SPEED);if(speed!=null){speed.removeModifier(SPEED);if(f.equals("fox")&&mode>0)speed.addTransientModifier(new AttributeModifier(SPEED,mode==2?1.1:mode==3?.45:.5,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));}var resist=p.getAttribute(Attributes.KNOCKBACK_RESISTANCE);if(resist!=null){resist.removeModifier(STABILITY);if(mode>0)resist.addTransientModifier(new AttributeModifier(STABILITY,mode==3?.85:.35,AttributeModifier.Operation.ADD_VALUE));}}
    private static boolean fits(Player p,int m,String f){if(m==0)return true;EntityDimensions d=m==3?(f.equals("fox")?EntityDimensions.scalable(6.8f,5):EntityDimensions.scalable(7.6f,2.8f)):f.equals("axolotl")?EntityDimensions.scalable(.65f,.45f):EntityDimensions.scalable(.6f,1.8f);return p.level().noCollision(p,d.makeBoundingBox(p.position()));}
    private static boolean change(State s,int m){if(!fits(s.p,m,s.fruit))return false;flight(s,s.fruit.equals("fox")&&m==2);s.mode=m;s.guardUntil=0;s.dashTicks=0;attributes(s.p,m,s.fruit);s.p.refreshDimensions();sync(s);return true;}
    public static int tailCount(int mode){return mode==3?9:mode==2?6:mode==1?3:0;}
    public static int dashRemaining(Player p){State s=states.get(p.getUUID());if(s==null)return 0;refill(s);return s.dashes;}
    public static int dashRest(Player p){State s=states.get(p.getUUID());return s==null?0:(int)Math.max(0,s.lastDash+80-now(p));}
    private static void refill(State s){if(now(s.p)-s.lastDash>=80)s.dashes=9;}
    public static boolean guarding(Player p){State s=states.get(p.getUUID());return s!=null&&s.fruit.equals("axolotl")&&valid(s)&&(s.guardUntil>now(p)||s.held==1&&now(p)-s.press>=12&&now(p)<=s.heartbeat&&now(p)<s.press+100)&&now(p)>=value(p,"cb_axolotl_catch_ready_");}
    public static void press(Player p,int move){String f=current(p);if(f.isEmpty()||move<0||move>2||restrained(p))return;State s=state(p,f);if(!valid(s)||s.held>=0)return;s.held=move;s.press=now(p);s.heartbeat=now(p)+15;}
    public static void heartbeat(Player p){State s=states.get(p.getUUID());if(s!=null)s.heartbeat=now(p)+15;}
    public static void cancelInput(Player p){State s=states.get(p.getUUID());if(s!=null){s.held=-1;s.guardUntil=0;}}
    public static void release(Player p,int move){State s=states.get(p.getUUID());if(s==null||s.held!=move)return;long held=now(p)-s.press;s.held=-1;Creeperborn.say(p,cast(p,s.fruit,move,held));}
    public static void input(Player p,int keys){State s=states.get(p.getUUID());if(s!=null){s.keys=keys;s.inputUntil=now(p)+10;}}
    public static String cast(Player p,String f,int move,long held){
        if(!unlocked(p,f)||!f.equals(current(p))||move<0||move>2||held<0)return "Select this fruit with G.";
        State s=state(p,f);if(!valid(s)||restrained(p))return "Powers unavailable while restrained or suppressed.";
        if(p.getFoodData().getFoodLevel()<=6)return "Eat before using fruit powers.";
        boolean hold=held>=20;int t=tier(p,f);long time=now(p);String key="cb_"+f+"_ready_"+move+"_";
        if(time<value(p,key))return "Move recovering: "+((value(p,key)-time+19)/20)+"s.";
        int cooldown;String result;
        if((f.equals("fox")&&move==1&&hold)||(f.equals("axolotl")&&move==2&&hold)){
            int next=s.mode==0?(f.equals("fox")&&t>=2?2:1):t>=3?(s.mode==3?(f.equals("fox")?2:1):3):t==2?(s.mode==2?0:2):0;
            if(!change(s,next))return "More open space is needed for that form.";
            cooldown=20;result=next==0?"Human form.":f.equals("fox")?(next==3?"Nine-Tails — heavy claws, 25-block jump dash, giant Beast Bomb!":next==2?"Golden Cloak — flight and nine linked Fox Flashes!":"Three-Tail Red Cloak!"):(next==3?"Giant Axolotl — combat and stronger absorption!":next==2?"Axolotl hybrid!":"Small Axolotl — fast swimming; sneak-use a fish with a water bucket!");
        }else if(f.equals("fox")){
            if(move==0&&!hold){int hits=cone(s,s.mode==3?12:7,s.mode==3?4:1.4,scaled(p,f,9,16,23)*(s.mode==3?1.8f:1),"fox",s.mode==3?1.4:.6);cooldown=s.mode==3?22:10;result="Chakra Claw"+(hits>0?" — hit!":"!");effect(p,p.getEyePosition().add(p.getLookAngle().scale(2)),30,10,1,0);}
            else if(move==0){for(int i=-1;i<=1;i++)launch(s,"flame",p.getLookAngle().yRot(i*.15f),scaled(p,f,6,10,15)*(s.mode==3?1.6f:1),.8,30,1.3,29);cooldown=70;result="Fox Fire!";}
            else if(move==1){refill(s);if(s.dashTicks>0)return "Finish the current dash first.";if(s.mode==2){if(s.dashes<=0)return "Fox Flash recovering — rest four seconds.";s.dashes--;cooldown=6;}else cooldown=s.mode==3?80:35;s.lastDash=time;s.dashDirection=dashDirection(p,s.keys,s.mode==3);s.dashTicks=s.mode==3?25:6;result=s.mode==3?"Nine-Tails jump dash — up to 25 blocks!":"Fox Flash — "+s.dashes+"/9";}
            else{float charge=hold?Math.min(1,held/(s.mode==3?70f:45f)):0;float damage=scaled(p,f,12,22,32)*(1+charge)*(s.mode==3?1.6f:1);double radius=(s.mode==3?5:2)+charge*(s.mode==3?5:3);launch(s,"fox",p.getLookAngle(),damage,radius,60,1.65,28);cooldown=hold?200:65;result=hold?"Tailed Beast Bomb!":"Mini Beast Bomb!";}
        }else{
            if(move==0&&!hold){launch(s,"water",p.getLookAngle(),scaled(p,f,6,10,16)*(s.mode==3?1.6f:1),.65,32,1.5,31);cooldown=25;result="Gill Jet!";}
            else if(move==0){s.regenUntil=time+100;cooldown=400;result="Regrowth — healing over five seconds.";}
            else if(move==1&&!hold){LivingEntity target=target(p,12+t*6,false);if(target==null)return "Aim at a fruit user, bender, or elemental creeper.";String power=power(target);if(power.isEmpty())return "That target has no power to copy.";store(s,power);cooldown=100;result="Power Imprint — "+borrowedName(power)+" stored!";}
            else if(move==1){if(time<value(p,"cb_axolotl_catch_ready_"))return "Absorption recovering.";s.guardUntil=time+(s.mode==3?100:60);cooldown=40;result="Absorption Guard — catch one incoming power!";}
            else{String power=borrowed(p);if(power.isEmpty())return "Copy a power with X first.";result=borrow(s,power);if(result.startsWith("No "))return result;clearBorrow(p);cooldown=80;}
        }
        value(p,key,time+cooldown);p.causeFoodExhaustion(hold?.65f:.2f);credit(s);sync(s);return result;
    }
    private static float scaled(Player p,String f,int a,int b,int c){int t=tier(p,f);return t>=3?c:t==2?b:a;}
    public static Vec3 dashDirection(Player p,int keys,boolean giant){Vec3 forward=p.getLookAngle();if(giant){Vec3 flat=new Vec3(forward.x,0,forward.z).normalize();return flat.lengthSqr()<.01?new Vec3(0,0,1):flat;}double yaw=Math.toRadians(p.getYRot());Vec3 right=new Vec3(Math.cos(yaw),0,Math.sin(yaw));Vec3 d=forward.scale((keys&2)!=0?-1:1);if((keys&4)!=0)d=right.scale(-1);if((keys&8)!=0)d=right;return d.normalize();}
    private static boolean enemy(Player p,LivingEntity e){return e!=p&&e.isAlive()&&!e.isSpectator()&&!p.isAlliedTo(e)&&!NaturePowers.proxy(e)&&!Azure.ownedProxy(e,p)&&!CelestialPowers.ownedProxy(e,p)&&(e instanceof Enemy||e instanceof Player);}
    private static LivingEntity target(Player p,double range,boolean hostile){Vec3 from=p.getEyePosition(),end=aim(p,from,p.getLookAngle(),range);LivingEntity best=null;double near=from.distanceTo(end)+.01;for(var e:p.level().getEntitiesOfClass(LivingEntity.class,new AABB(from,end).inflate(.6))){if(e==p||!e.isAlive()||e.isSpectator()||hostile&&!enemy(p,e))continue;var cross=e.getBoundingBox().inflate(.35).clip(from,end);if(cross.isPresent()&&cross.get().distanceTo(from)<near){near=cross.get().distanceTo(from);best=e;}}return best;}
    private static Vec3 aim(Player p,Vec3 from,Vec3 dir,double length){var hit=p.level().clip(new ClipContext(from,from.add(dir.scale(length)),ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,p));return hit.getType()==HitResult.Type.MISS?from.add(dir.scale(length)):hit.getLocation();}
    public static String power(LivingEntity target){if(target instanceof Player p){String extra=Dark.unlocked(p)?Dark.choice(p):"";if(!extra.isEmpty()&&Dark.fruitTier(p,extra)>0)return extra;if(p.entityTags().contains("cb_mode_fruit"))for(String f:Dark.FRUITS)if(p.getUUID().equals(FruitClaims.owner(f)))return f;Element element=Progress.selected(p);if(element!=null)return element.key();for(String f:Dark.FRUITS)if(p.getUUID().equals(FruitClaims.owner(f)))return f;}Element e=Guardians.element(target);if(e!=null)return e.key();e=ElementalCreepers.element(target);if(e!=null)return e.key();for(String f:Dark.FRUITS)if(target.entityTags().contains("cb_fruitborn_"+f))return f;return "";}
    public static boolean poweredHit(Player p,LivingEntity e,String power,DamageSource source,float amount){Origin old=origin.get();origin.set(new Origin(p,power));try{return e.hurtServer((ServerLevel)p.level(),source,amount);}finally{if(old==null)origin.remove();else origin.set(old);}}
    public static void beginElement(Player p,Element e){origin.set(new Origin(p,e.key()));}
    public static void endElement(){origin.remove();}
    public static String activeFruit(Player p,String... choices){for(String f:choices)if(p.getUUID().equals(FruitClaims.owner(f)))return f;return "";}
    public static boolean intercept(Player p,DamageSource source,float amount){if(unlocked(p,"fox")&&mode(p)>0&&source.is(DamageTypeTags.IS_FALL)&&!Phoenix.bypass(source))return true;if(amount<=0||Phoenix.bypass(source)||!guarding(p))return false;Origin attack=origin.get();if(attack==null||attack.p==p||attack.p.level()!=p.level()||!known(attack.power))return false;State s=states.get(p.getUUID());if(p.distanceToSqr(attack.p)>(s.mode==3?4096:1600))return false;store(s,attack.power);s.guardUntil=0;s.held=-1;value(p,"cb_axolotl_ready_1_",now(p)+40);value(p,"cb_axolotl_catch_ready_",now(p)+(s.mode==3?100:160));if(source.getDirectEntity() instanceof net.minecraft.world.entity.projectile.Projectile projectile)projectile.discard();p.heal(s.mode==3?3:1);Creeperborn.say(p,"Absorbed! "+borrowedName(attack.power)+" — tap C to use.");credit(s);sync(s);return true;}
    private static boolean known(String power){return Dark.FRUITS.contains(power)||Element.parse(power)!=null;}
    private static void store(State s,String power){clearBorrow(s.p);s.p.addTag("cb_axolotl_borrow_"+power);value(s.p,"cb_axolotl_expiry_",now(s.p)+(tier(s.p,"axolotl")*600));particles(s.p,s.p.getEyePosition(),0x67E8D4,24);}
    private static void clearBorrow(Player p){for(String tag:Set.copyOf(p.entityTags()))if(tag.startsWith("cb_axolotl_borrow_")||tag.startsWith("cb_axolotl_expiry_"))p.removeTag(tag);}
    public static String borrowed(Player p){if(!unlocked(p,"axolotl")||now(p)>=value(p,"cb_axolotl_expiry_"))return "";for(String tag:p.entityTags())if(tag.startsWith("cb_axolotl_borrow_")){String f=tag.substring(18);return known(f)?f:"";}return "";}
    public static String borrowedName(String f){return switch(f){case "earth"->"Boulder Smash";case "water"->"Water Bolt";case "fire"->"Fire Bolt";case "air"->"Air Blast";case "rubber"->"Stretch Punch";case "door"->"Door Step";case "phoenix"->"Healing Flame";case "lightning"->"Lightning Bolt";case "dark"->"Dark Grasp";case "op"->"Gamma Knife";case "gravity"->"Gravity Press";case "string"->"Five-Color Slash";case "paw"->"Paw Cannon";case "tremor"->"Quake Punch";case "love"->"Love Arrow";case "sand"->"Desert Blade";case "ice"->"Ice Spear";case "magma"->"Magma Fist";case "azure"->"Dragon Breath";case "tree"->"Root Strike";case "petal"->"Bloom Strike";case "glint"->"Light Laser";case "straw"->"Straw Talons";case "flame"->"Fire Fist";case "buddha"->"Impact Palm";case "fox"->"Mini Beast Bomb";case "axolotl"->"Gill Jet";default->"Unknown";};}
    private static String borrow(State s,String f){Player p=s.p;float damage=scaled(p,"axolotl",8,14,21)*(s.mode==3?1.35f:1);if(f.equals("phoenix")){p.heal(s.mode==3?8:5);effect(p,p.position().add(0,1,0),32,20,2,0);}else if(f.equals("door")){Vec3 end=aim(p,p.getEyePosition(),p.getLookAngle(),8+tier(p,"axolotl")*2).subtract(0,p.getEyeHeight(),0);if(!safeTeleport(p,end))return "No safe Door Step exit.";}else if(Set.of("rubber","op","straw","petal").contains(f)){LivingEntity e=target(p,f.equals("rubber")?20:10,true);if(e==null)return "No enemy in reach.";hit(s,e,f,damage);particles(p,e.getBoundingBox().getCenter(),color(f),20);}else if(Set.of("dark","gravity","tree","tremor","buddha").contains(f)){LivingEntity e=target(p,24,true);if(e==null)return "No enemy in reach.";hit(s,e,f,damage);if(f.equals("dark"))push(e,p.position().subtract(e.position()).normalize().scale(1.1));effect(p,e.position().add(0,.8,0),32,15,2,0);}else launch(s,f,p.getLookAngle(),damage,f.equals("fox")?3:.65,40,1.5,f.equals("fox")?28:31);return "Borrowed "+borrowedName(f)+"!";}
    private static void hit(State s,LivingEntity e,String power,float amount){if(!enemy(s.p,e))return;boolean accepted=poweredHit(s.p,e,power,s.p.damageSources().playerAttack(s.p),amount*(float)Mastery.multiplier(s.p));if(!accepted)return;if(Set.of("flame","fire","magma","azure").contains(power))e.setRemainingFireTicks(60);if(Set.of("ice","water","sand","tree","gravity","love","string","dark").contains(power))e.addEffect(new MobEffectInstance(MobEffects.SLOWNESS,60,1,false,false,true));if(power.equals("air")||power.equals("paw")||power.equals("tremor")||power.equals("buddha")||power.equals("water"))push(e,e.position().subtract(s.p.position()).normalize().scale(1.1).add(0,.25,0));}
    private static int cone(State s,double reach,double width,float damage,String power,double force){Vec3 from=s.p.getEyePosition(),end=aim(s.p,from,s.p.getLookAngle(),reach);int count=0;for(var e:s.level.getEntitiesOfClass(LivingEntity.class,new AABB(from,end).inflate(width)))if(enemy(s.p,e)&&s.p.hasLineOfSight(e)&&(e.getBoundingBox().inflate(width*.5).clip(from,end).isPresent()||e.getBoundingBox().contains(from))){hit(s,e,power,damage);push(e,s.p.getLookAngle().scale(force).add(0,.2,0));count++;}return count;}
    private static void push(LivingEntity e,Vec3 force){if(e instanceof Player p)Rubber.impulse(p,force);else e.setDeltaMovement(force);}
    private static boolean safeTeleport(Player p,Vec3 end){ServerLevel l=(ServerLevel)p.level();if(!l.hasChunkAt(BlockPos.containing(end))||!l.getWorldBorder().isWithinBounds(BlockPos.containing(end))||!DoorSpace.fits(l,p,end)||StringFruit.blocked(p,end))return false;if(p instanceof ServerPlayer sp)return sp.teleportTo(l,end.x,end.y,end.z,Set.of(),p.getYRot(),p.getXRot(),false);p.snapTo(end.x,end.y,end.z);return true;}
    private static void launch(State s,String power,Vec3 dir,float damage,double radius,double range,double speed,int kind){if(shots.stream().filter(q->q.p==s.p).count()>=12)return;Shot q=new Shot();q.p=s.p;q.level=s.level;q.fruit=s.fruit;q.power=power;q.at=s.p.getEyePosition().add(s.p.getLookAngle().scale(giantFox(s.p)?2.3:giantAx(s.p)?2:.7));q.dir=dir.normalize();q.damage=damage;q.radius=radius;q.range=range;q.speed=speed;q.kind=kind;float size=kind==28?(float)Math.max(.35,radius*.2):kind==29?.5f:.35f;q.visual=effect(s.p,q.at,kind,100,size,s.p.getYRot());shots.add(q);}
    private static void end(Shot q){if(q.visual!=null){visuals.remove(q.visual.getUUID());q.visual.discard();}shots.remove(q);}
    private static void explode(Shot q,Vec3 at){State s=states.get(q.p.getUUID());if(s==null)return;for(var e:q.level.getEntitiesOfClass(LivingEntity.class,new AABB(at,at).inflate(q.radius+1)))if(enemy(q.p,e)&&e.getBoundingBox().getCenter().distanceTo(at)<=q.radius+e.getBbWidth()/2&&q.level.clip(new ClipContext(at,e.getBoundingBox().getCenter(),ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,q.p)).getType()==HitResult.Type.MISS)hit(s,e,q.power,q.damage);effect(q.p,at,32,24,(float)q.radius,0);particles(q.p,at,color(q.power),45);}
    private static int color(String f){return switch(f){case "fox","dark"->0x8723B8;case "flame","fire","magma","azure"->0xFF6B23;case "ice","water","axolotl"->0x68E5EA;case "tree","earth"->0x78AC49;case "love","petal"->0xF579BD;case "buddha","glint","lightning"->0xFFD34C;default->0xECE7D8;};}
    private static void particles(Player p,Vec3 at,int color,int count){if(p.level() instanceof ServerLevel l)l.sendParticles(new DustParticleOptions(color,.7f),at.x,at.y,at.z,count,.3,.3,.3,.02);}
    public static float damage(Player p,DamageSource source,float amount){if(Phoenix.bypass(source))return amount;State s=states.get(p.getUUID());if(s==null||!valid(s)||s.mode==0)return amount;if(source.is(DamageTypeTags.IS_FALL)&&s.fruit.equals("fox"))return 0;return amount*(s.fruit.equals("fox")?(s.mode==3?.45f:s.mode==2?.6f:.8f):s.mode==3?.6f:1);}
    public static void tickPlayer(Player p){State s=states.get(p.getUUID());if(s==null)return;if(!valid(s)){forget(p);return;}long time=now(p);if(s.held>=0&&(!s.fruit.equals(current(p))||time>s.heartbeat))cancelInput(p);if(s.mode>0&&p.getFoodData().getFoodLevel()<=6){change(s,0);Creeperborn.say(p,"Transformation ended — eat to recover.");}if(time%20==0){boolean active=s.mode>0&&(p.getDeltaMovement().lengthSqr()>.002||s.recent+200>time||s.held>=0);if(active)Mastery.set(p,"cb_"+s.fruit+"_time_",Mastery.get(p,"cb_"+s.fruit+"_time_")+1);if(s.mode>0)p.causeFoodExhaustion(s.flight?.025f:.015f);if(time<s.regenUntil){p.heal(s.mode==3?2:1);particles(p,p.position().add(0,.5,0),0xFF99C3,12);}}
        if(s.fruit.equals("fox")&&tier(p,"fox")==2&&s.mode==1)change(s,2);
        if(s.dashTicks>0){if(restrained(p)){s.dashTicks=0;}else{int remaining=s.dashTicks--;boolean giant=s.mode==3;Vec3 motion=s.dashDirection.scale(giant?1:1.6).add(0,giant?(remaining>12?.22:-.18):0,0);Vec3 old=p.position();if(StringFruit.blocked(p,old.add(motion))||!s.level.hasChunkAt(BlockPos.containing(old.add(motion)))||!s.level.getWorldBorder().isWithinBounds(BlockPos.containing(old.add(motion))))s.dashTicks=0;else{p.move(MoverType.SELF,motion);p.setDeltaMovement(Vec3.ZERO);p.resetFallDistance();if(p instanceof ServerPlayer sp){sp.connection.teleport(p.getX(),p.getY(),p.getZ(),p.getYRot(),p.getXRot());sp.connection.resetPosition();sp.connection.send(new net.minecraft.network.protocol.game.ClientboundSetEntityMotionPacket(p));}if(p.position().distanceToSqr(old)<.01)s.dashTicks=0;for(var e:s.level.getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(.8)))if(enemy(p,e)&&p.hasLineOfSight(e)){hit(s,e,"fox",giant?28:10);push(e,s.dashDirection.scale(1.2));}particles(p,p.position().add(0,.6,0),s.mode==2?0xFFCF39:0xD82623,3);}}}
        if(s.held>=0&&time%3==0){if(s.fruit.equals("fox")&&s.held==2){float charge=Math.min(1,(time-s.press)/(s.mode==3?70f:45f));effect(p,p.getEyePosition().add(p.getLookAngle().scale(s.mode==3?2.5:1.2)),28,4,.2f+charge*(s.mode==3?1.5f:.7f),p.getYRot());}else if(s.fruit.equals("axolotl")&&s.held==1&&guarding(p))particles(p,p.getEyePosition().add(p.getLookAngle().scale(.6)),0x63EEDB,5);}
        if(s.mode==2&&s.fruit.equals("fox")&&!s.flight)flight(s,true);int flags=flags(p);if(flags!=s.synced||time%20==0){s.synced=flags;sync(s);}if(unlocked(p,"axolotl")&&borrowed(p).isEmpty())clearBorrow(p);
    }
    public static void tick(MinecraftServer server){for(var p:server.getPlayerList().getPlayers())tickPlayer(p);for(Shot q:List.copyOf(shots)){State s=states.get(q.p.getUUID());if(s==null||!valid(s)||q.level!=q.p.level()){end(q);continue;}Vec3 next=q.at.add(q.dir.scale(q.speed)),end=aim(q.p,q.at,q.dir,q.speed);LivingEntity hit=null;double nearest=q.at.distanceTo(end)+.001;for(var e:q.level.getEntitiesOfClass(LivingEntity.class,new AABB(q.at,end).inflate(.5)))if(enemy(q.p,e)){var cross=e.getBoundingBox().inflate(.25).clip(q.at,end);if(cross.isPresent()&&cross.get().distanceTo(q.at)<nearest){hit=e;nearest=cross.get().distanceTo(q.at);}}if(hit!=null){Vec3 at=q.at.add(q.dir.scale(nearest));if(q.radius>1)explode(q,at);else{hit(s,hit,q.power,q.damage);particles(q.p,at,color(q.power),15);}end(q);continue;}if(end.distanceToSqr(next)>.0001){if(q.radius>1)explode(q,end);end(q);continue;}q.at=next;q.distance+=q.speed;if(q.distance>=q.range){if(q.radius>1)explode(q,q.at);end(q);continue;}if(q.visual!=null)q.visual.snapTo(next.x,next.y,next.z);particles(q.p,q.at,color(q.power),2);}for(Visual v:List.copyOf(visuals.values()))if(v.entity.isRemoved()||now(v.p)>=v.until||!v.p.isAlive()||v.p.level()!=v.entity.level()){v.entity.discard();visuals.remove(v.entity.getUUID());}}
    public static InteractionResult catchFish(Player p,InteractionHand hand,Entity entity){if(!small(p)||!p.isShiftKeyDown()||!(entity instanceof AbstractFish fish)||!fish.isAlive()||!p.getItemInHand(hand).is(Items.WATER_BUCKET))return InteractionResult.PASS;if(!(p.level() instanceof ServerLevel))return InteractionResult.SUCCESS;if(p.distanceToSqr(fish)>16||!p.hasLineOfSight(fish))return InteractionResult.FAIL;ItemStack bucket=fish.getBucketItemStack();fish.saveToBucketTag(bucket);p.setItemInHand(hand,bucket);fish.discard();return InteractionResult.SUCCESS;}
    public static int flags(Player p){State s=states.get(p.getUUID());if(s==null||!valid(s))return 0;return (s.fruit.equals("fox")?1:2)|(s.mode<<2)|(tier(p,s.fruit)<<4)|(guarding(p)?64:0)|(s.dashTicks>0?128:0);}
    private static void sync(State s){if(!(s.p.level() instanceof ServerLevel l))return;int flags=flags(s.p);for(var viewer:l.getServer().getPlayerList().getPlayers())if(ServerPlayNetworking.canSend(viewer,ZoanPayload.TYPE))ServerPlayNetworking.send(viewer,new ZoanPayload(s.p.getId(),flags));}
    private static Display.BlockDisplay effect(Player p,Vec3 at,int kind,int duration,float size,float yaw){var d=EntityTypes.BLOCK_DISPLAY.create((ServerLevel)p.level(),EntitySpawnReason.TRIGGERED);if(d==null)return null;d.addTag("cb_temporary_rock");d.setCustomName(Component.literal("cb_celestial_"+kind+"|"+p.getUUID()));d.setCustomNameVisible(false);d.setBlockState(Blocks.STONE.defaultBlockState());d.snapTo(at.x,at.y,at.z);var a=(com.sibcraft.creeperborn.mixin.PunchDisplayAccessor)d;a.creeperborn$duration(0);a.creeperborn$positionDuration(0);a.creeperborn$width(128);a.creeperborn$height(64);a.creeperborn$view(5);d.setTransformation(new com.mojang.math.Transformation(new org.joml.Vector3f(),new org.joml.Quaternionf().rotationY((float)Math.toRadians(-yaw)),new org.joml.Vector3f(size,size,size),new org.joml.Quaternionf()));if(!p.level().addFreshEntity(d))return null;visuals.put(d.getUUID(),new Visual(p,d,now(p)+duration));return d;}
    public static void tickVisual(Entity e){if(!(e.level() instanceof ServerLevel)||e.getCustomName()==null)return;String n=e.getCustomName().getString();if(!n.matches("cb_celestial_(28|29|30|31|32)\\|.*"))return;Visual v=visuals.get(e.getUUID());if(v==null&&e.tickCount>2||v!=null&&now(e)>=v.until){e.discard();visuals.remove(e.getUUID());}}
    public static void forget(Player p){State s=states.get(p.getUUID());if(s==null){recover(p);return;}flight(s,false);s.mode=0;s.guardUntil=0;attributes(p,0,"");p.refreshDimensions();sync(s);states.remove(p.getUUID());for(Shot q:List.copyOf(shots))if(q.p==p)end(q);for(Visual v:List.copyOf(visuals.values()))if(v.p==p){v.entity.discard();visuals.remove(v.entity.getUUID());}}
    public static void clear(){for(State s:List.copyOf(states.values()))forget(s.p);states.clear();shots.clear();visuals.clear();origin.remove();clearClient();}
    public static String status(Player p,String f){if(!unlocked(p,f))return f+": locked";return f.equals("fox")?"Nine-Tails T"+tier(p,f)+" | Z Claw / hold Fox Fire | X Flash / hold forms | C Bomb / hold Beast Bomb | "+dashRemaining(p)+"/9 flashes":"Axolotl T"+tier(p,f)+" | Z Gill Jet / hold Regrowth | X Copy / hold Absorb | C "+(borrowed(p).isEmpty()?"borrowed move":borrowedName(borrowed(p)))+" / hold forms | swims + breathes underwater";}
}
